CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,cgpa REAL NOT NULL CHECK(cgpa BETWEEN 0 AND 10),role TEXT NOT NULL DEFAULT 'student');
CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY,company TEXT NOT NULL,title TEXT NOT NULL,minimum REAL NOT NULL,deadline TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applications(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),job_id INTEGER REFERENCES jobs(id),status TEXT NOT NULL DEFAULT 'Applied',UNIQUE(user_id,job_id));
